import{_ as t,o as n,c as e,a5 as d}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse(`{"title":"404 not-found notfound not found","description":"\\\\{ path: '/:pathMatch(. ) ', redirect: \\\\{ name: 'not found' \\\\}, meta: \\\\{ public: true \\\\}, \\\\}, 1. 作用 这是 Vue Router 4 的 兜底路由（catch all route）。","frontmatter":{"title":"404 not-found notfound not found","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"\\\\{ path: '/:pathMatch(. ) ', redirect: \\\\{ name: 'not found' \\\\}, meta: \\\\{ public: true \\\\}, \\\\}, 1. 作用 这是 Vue Router 4 的 兜底路由（catch all route）。","sidebarWeight":6,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/404 not-found notfound not found.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/404 not-found notfound not found.md","filePath":"posts/Vue系统教程/04-路由与状态管理/404 not-found notfound not found.md"}`),u={name:"posts/Vue系统教程/04-路由与状态管理/404 not-found notfound not found.md"};function a(r,o,l,c,i,f){return n(),e("div",null,[...o[0]||(o[0]=[d('<div><h1 id="_404-not-found-notfound-not-found" tabindex="-1">404 not-found notfound not found <a class="header-anchor" href="#_404-not-found-notfound-not-found" aria-label="Permalink to &quot;404 not-found notfound not found&quot;">​</a></h1><blockquote><p>本节目标：理解“404 not-found notfound not found”的核心思路，并能把它用于实际开发或面试表达。 { path: &#39;/:pathMatch(.<em>)</em>&#39;, redirect: { name: &#39;not-found&#39; }, meta: { public: true }, },</p></blockquote><h3 id="_1-作用" tabindex="-1">1. 作用 <a class="header-anchor" href="#_1-作用" aria-label="Permalink to &quot;1. 作用&quot;">​</a></h3><p>这是 Vue Router 4 的<strong><strong>兜底路由（catch-all route）</strong></strong>。</p><ul><li><code>/:pathMatch(.*)*</code> 会匹配所有没有命中的路径。</li><li><code>redirect: { name: &#39;not-found&#39; }</code> 会把用户导向你定义好的 <code>not-found</code> 页面。</li><li><code>meta: { public: true }</code> 确保未登录用户访问不存在的路由时，不会被守卫拦截，还能正常看到 404 页。</li></ul><h3 id="_2-好处" tabindex="-1">2. 好处 <a class="header-anchor" href="#_2-好处" aria-label="Permalink to &quot;2. 好处&quot;">​</a></h3><ul><li><strong><strong>统一处理</strong></strong>：不论用户输什么奇怪地址，都能落到 <code>not-found</code> 页面。</li><li><strong><strong>安全性</strong></strong>：不会暴露系统结构（不匹配的路由不会报错，而是跳转 404）。</li><li><strong><strong>守卫配合</strong></strong>：有了 <code>public: true</code>，不需要登录也能访问 404 页。</li></ul><h3 id="_3-潜在问题" tabindex="-1">3. 潜在问题 <a class="header-anchor" href="#_3-潜在问题" aria-label="Permalink to &quot;3. 潜在问题&quot;">​</a></h3><ul><li>你在 <code>children</code> 里也定义了 <code>not-found</code> 页面： { path: &#39;not-found&#39;, name: &#39;not-found&#39;, component: () =&gt; import(&#39;@/views/not-found/page.vue&#39;), meta: { public: true }, } 这样相当于有两种方式进入 <code>not-found</code>： <ul><li>显式访问 <code>/not-found</code></li><li>未匹配时重定向过去 → <strong><strong>没问题</strong></strong>，但算是“重复入口”。</li></ul></li><li>如果想避免 <code>/not-found</code> 被用户直接访问，也可以只保留兜底路由，不显式写 <code>/not-found</code>。</li></ul><h3 id="_4-最佳实践建议" tabindex="-1">4. 最佳实践建议 <a class="header-anchor" href="#_4-最佳实践建议" aria-label="Permalink to &quot;4. 最佳实践建议&quot;">​</a></h3><ul><li>保留现在的写法，没错。</li><li>如果你喜欢整洁，可以： <ul><li>移除 <code>path: &#39;not-found&#39;</code> 的定义，只留兜底路由；</li><li>直接在兜底路由里用 <code>component</code> 而不是 <code>redirect</code>，少跳转一步： { path: &#39;/:pathMatch(.<em>)</em>&#39;, name: &#39;not-found&#39;, component: () =&gt; import(&#39;@/views/not-found/page.vue&#39;), meta: { public: true }, }</li></ul></li></ul><p>这样用户输错地址就直接落到 404 页，而不是“先重定向再加载”。</p></div>',1)])])}const p=t(u,[["render",a]]);export{h as __pageData,p as default};
